/**
 * The Magic Patch rule catalog.
 *
 * Rules are narrow on purpose. Each either rewrites a construct it can prove
 * safe, or escalates — never guesses. Coverage comes from adding rules, not
 * from widening one.
 */
import type { GeneratedTest, Match, MigrationRule, TestContext } from './types'
import { classifyWidgetMutation } from './widgetMutation'

/** Keeps generated files obviously generated, and traceable back to the rule. */
function header(rule: string, context: TestContext, matches: readonly Match[]) {
  return [
    `// Generated by Magic Patch. Do not edit — regenerate instead.`,
    `// pack: ${context.pack}`,
    `// file: ${context.file}`,
    `// rule: ${rule}`,
    ...matches.map((m) => `//   line ${m.line}: ${m.text}`)
  ].join('\n')
}

/**
 * `this.type = this.type ?? undefined` — a defensive no-op.
 *
 * `type` is identity in the published API and has no setter, so this throws
 * inside the constructor and the node fails to construct at all. Deleting the
 * line is exactly equivalent to what it did before.
 *
 * Appears both as written source and as TypeScript's compiled `??` output.
 */
const TYPE_NOOP_PATTERNS = [
  /^[ \t]*this\.type\s*=\s*this\.type\s*\?\?\s*undefined\s*;?[ \t]*$/,
  /^[ \t]*this\.type\s*=\s*\((_\w+)\s*=\s*this\.type\)\s*!==\s*null\s*&&\s*\1\s*!==\s*void 0\s*\?\s*\1\s*:\s*undefined\s*;?[ \t]*$/
]

const typeWriteNoop: MigrationRule = {
  id: 'type-write-noop',
  severity: 'breaking',
  // Assigning a value to itself; deletion is equivalent by inspection.
  mechanicallySafe: true,
  replacement: {
    api: 'none — remove the line; use graph.replaceNode() to change a type',
    declaredAt: 'src/platform/nodeApi/nodeHandle.ts (type is readonly)'
  },
  guidance: `
\`node.type\` is identity and cannot be assigned. A self-assignment
(\`this.type = this.type ?? undefined\`) is a no-op that now throws in the
constructor, so the node never constructs. Delete the line. If a type genuinely
needs to change, build a replacement node with \`graph.replaceNode()\`.
`.trim(),
  apply(lines, report) {
    lines.forEach((line, i) => {
      if (line === null) return
      if (TYPE_NOOP_PATTERNS.some((rx) => rx.test(line))) {
        report({ line: i + 1, text: line.trim() })
        lines[i] = null
      }
    })
  },
  generateTest(matches, context): GeneratedTest | undefined {
    const types = context.registeredTypes ?? []
    // Without the registered types there is nothing concrete to exercise, and a
    // test asserting "the file parses" would prove nothing.
    if (!types.length) return undefined

    const list = types.map((t) => `  ${JSON.stringify(t)}`).join(',\n')
    return {
      filename: `${context.pack}.type-write-noop.test.ts`,
      equivalence: [
        'node type is unchanged by construction',
        'each type reports the identity it was registered under'
      ],
      fix: ['every registered node type constructs instead of throwing'],
      source: `${header('type-write-noop', context, matches)}
//
// Run this file against BOTH the original and the converted source.
//
//   equivalence  must pass on both — the conversion changed no behaviour
//   fix          must FAIL on the original and PASS on the converted source
//
// node.type is identity and has no setter. The removed self-assignment threw
// inside the constructor, so createNode returned null for every type below.
import { describe, expect, it } from 'vitest'

import { LiteGraph } from '@/lib/litegraph/src/litegraph'

const REGISTERED_TYPES = [
${list}
]

describe(${JSON.stringify(context.pack)}, () => {
  describe('equivalence — must pass before and after', () => {
    it.each(REGISTERED_TYPES)('%s is registered', (type) => {
      expect(LiteGraph.registered_node_types[type]).toBeDefined()
    })

    it.each(REGISTERED_TYPES)('%s keeps its registered identity', (type) => {
      const node = LiteGraph.createNode(type)
      // Skipped rather than asserted when construction is the thing being
      // fixed, so this section stays green on the original source.
      if (node) expect(node.type).toBe(type)
    })
  })

  describe('fix — must fail before, pass after', () => {
    it.each(REGISTERED_TYPES)('%s constructs', (type) => {
      expect(LiteGraph.createNode(type)).not.toBeNull()
    })
  })
})
`
    }
  },
  cases: [
    {
      name: 'source form',
      before:
        'class A {\n  ctor() {\n    this.type = this.type ?? undefined;\n  }\n}',
      after: 'class A {\n  ctor() {\n  }\n}'
    },
    {
      name: 'compiled form',
      before:
        'onConstructed() {\n    var _a;\n    this.type = (_a = this.type) !== null && _a !== void 0 ? _a : undefined;\n    this.__c = true;\n}',
      after: 'onConstructed() {\n    var _a;\n    this.__c = true;\n}'
    },
    {
      name: 'leaves a real type assignment alone',
      before: "this.type = 'MyNode';",
      after: "this.type = 'MyNode';"
    }
  ]
}

/**
 * `node.outputs[i].links.push(...)` and friends.
 *
 * Escalated, never rewritten. The right replacement depends on intent that is
 * not recoverable from the line: re-homing links needs `moveLinksTo()` to
 * preserve link ids, while rebuilding a mirror needs deleting outright. Picking
 * wrong silently changes the serialized workflow.
 */
const OUTPUT_LINKS_WRITE =
  /\.outputs\s*\[[^\]]+\]\s*\.links\s*(?:\.push\(|\.splice\(|\.pop\(|=[^=])/

const outputLinksMutation: MigrationRule = {
  id: 'output-links-mutation',
  severity: 'breaking',
  mechanicallySafe: false,
  replacement: {
    api: 'output.moveLinksTo() / output.connectTo() / output.disconnect()',
    declaredAt: 'src/platform/nodeApi/slotHandle.ts'
  },
  guidance: `
\`output.links\` is no longer a mutable mirror. Choose by intent:

- **Re-homing links to another output of the same node** —
  \`output.moveLinksTo(target)\`. Preserves link ids, so the serialized
  workflow is unchanged. This is what you want when migrating your own slots.
- **Creating a connection** — \`output.connectTo(nodeId, inputRef)\`.
- **Removing connections** — \`output.disconnect()\`.
- **Reading** — \`output.links()\` returns a frozen snapshot that is safe to
  iterate while disconnecting.

Never rebuild the array by hand: connectivity is derived, not stored.
`.trim(),
  apply(lines, report) {
    lines.forEach((line, i) => {
      if (line === null || !OUTPUT_LINKS_WRITE.test(line)) return
      report({
        line: i + 1,
        text: line.trim(),
        escalation:
          'Replacement depends on intent (re-home vs. rebuild); moveLinksTo preserves link ids, reconnecting does not.'
      })
    })
  },
  cases: [
    {
      name: 'push',
      before: 'node.outputs[3].links.push(link);',
      escalates: true
    },
    {
      name: 'splice',
      before: 'node.outputs[slot].links.splice(i, 1);',
      escalates: true
    },
    {
      name: 'reads are not flagged',
      before: 'for (const l of node.outputs[0].links) {}',
      after: 'for (const l of node.outputs[0].links) {}'
    }
  ]
}

/**
 * `input.link = null`.
 *
 * The identical text is correct on a *serialized* workflow payload and wrong on
 * a live node. easy-use's `image_chooser/prompt.js` filters `p.workflow.nodes`
 * before submitting a prompt and nulls `link` there legitimately.
 *
 * Not decidable by regex, so this escalates — and says so, loudly, when the file
 * shows signs of manipulating serialized data.
 */
const LINK_WRITE = /\.link\s*=\s*(?:null|undefined)/
const SERIALIZED_HINT =
  /\b\w*\.(?:workflow|prompt)\b|\bworkflow\s*\.\s*nodes\b|\bJSON\.parse\b/

const inputLinkWrite: MigrationRule = {
  id: 'input-link-write',
  severity: 'breaking',
  mechanicallySafe: false,
  replacement: {
    api: 'input.disconnect() / input.source()',
    declaredAt: 'src/platform/nodeApi/slotHandle.ts'
  },
  guidance: `
Assignment to \`input.link\` has no effect — connectivity is derived. Use
\`input.disconnect()\` to break a connection and \`input.source()\` to read one.

**Check what the object is first.** On a serialized workflow payload
(\`p.workflow.nodes[i].inputs\`), \`link = null\` is plain data manipulation and
is correct as written — do not convert it.
`.trim(),
  apply(lines, report) {
    const text = lines.filter((l) => l !== null).join('\n')
    const serialized = SERIALIZED_HINT.test(text)
    lines.forEach((line, i) => {
      if (line === null || !LINK_WRITE.test(line)) return
      report({
        line: i + 1,
        text: line.trim(),
        escalation: serialized
          ? 'File also manipulates serialized workflow data; this may be plain JSON, not a live slot. Do not convert without checking.'
          : 'Confirm the target is a live input slot before converting.'
      })
    })
  },
  cases: [
    {
      name: 'live slot',
      before: 'node.inputs[0].link = null;',
      escalates: true
    },
    {
      name: 'serialized payload still escalates rather than being rewritten',
      before:
        'p.workflow.nodes.forEach((n) => n.inputs.forEach((i) => { i.link = null }))',
      escalates: true
    }
  ]
}

/**
 * Widget-array mutation: `splice`, whole-array assignment, `length =`, `push`.
 *
 * Escalated, because the same call means three different things and only
 * reading the indices tells them apart:
 *
 * - remove and reinsert at the **same** index -> cache invalidation, replaced
 *   by `widget.setOptions()` (kjnodes `setgetnodes.js:998`)
 * - different index -> a real move, `widgets.move()`
 * - whole-array rewrite -> `widgets.reorder()`
 * - `length = n` -> removal, and the pack must already be calling
 *   `onRemove()` by hand because assigning length skips teardown
 */
const WIDGETS_MUTATION =
  /\.widgets\s*(?:\.splice\(|\.push\(|\.pop\(|\.length\s*=[^=]|=\s*\[)/

const widgetsArrayMutation: MigrationRule = {
  id: 'widgets-array-mutation',
  severity: 'breaking',
  mechanicallySafe: false,
  replacement: {
    api: 'widgets.reorder() / .move() / .add() / .remove() / widget.setOptions()',
    declaredAt: 'src/platform/nodeApi/widgetHandle.ts'
  },
  guidance: `
\`node.widgets\` is no longer the source of truth for render order — the store
is. Classify before converting:

| Shape | Meaning | Replacement |
|---|---|---|
| \`splice(i,1)\` then \`splice(i,0,w)\` | cache invalidation, **not** a reorder | \`widget.setOptions(...)\` |
| \`splice\` to a different index | a move | \`widgets.move(name, index)\` |
| whole-array assignment | a reorder | \`widgets.reorder(names)\` |
| \`widgets.length = n\` | truncation | \`widgets.remove(name)\` per widget |
| \`push\` | append | \`widgets.add(def)\` |

Never assign a new array: the renderer tracks array identity, so replacing it
stops updates. \`reorder\` splices in place for that reason, and throws on a
partial list rather than dropping the widgets you omitted.
`.trim(),
  apply(lines, report) {
    lines.forEach((line, i) => {
      if (line === null || !WIDGETS_MUTATION.test(line)) return
      // Classified rather than reported generically: the indices distinguish
      // invalidation from a move from a reorder, and the agent needs to be told
      // which, not asked to work it out.
      const mutation = classifyWidgetMutation(lines, i)
      report({
        line: i + 1,
        text: line.trim(),
        escalation: mutation
          ? `[${mutation.kind}] ${mutation.instruction}`
          : 'Unclassified widget-array mutation; read the indices before converting.'
      })
    })
  },
  cases: [
    { name: 'splice', before: 'this.widgets.splice(idx, 1);', escalates: true },
    { name: 'push', before: 'node.widgets.push(w);', escalates: true },
    {
      name: 'truncate',
      before: 'this.widgets.length = isConvertedWidget;',
      escalates: true
    },
    {
      name: 'assignment',
      before: 'node.widgets = [w1, w2];',
      escalates: true
    },
    {
      name: 'reads are not flagged',
      before: 'const n = node.widgets.length;',
      after: 'const n = node.widgets.length;'
    }
  ]
}

/**
 * The converted-widget protocol: `widget.type = 'converted-widget'`.
 *
 * Escalated despite the obvious one-line replacement (`widget.hidden = true`),
 * because the old hack **also** installed a `serializeValue` that suppressed
 * persistence unless the matching input was linked. `hidden` and `serialize`
 * are orthogonal in the published API, so a literal conversion changes what the
 * workflow serializes — a wire-format change.
 */
const CONVERTED_WIDGET = /\.type\s*=\s*(?:CONVERTED_TYPE|["'`]converted-widget)/

const convertedWidgetProtocol: MigrationRule = {
  id: 'converted-widget-protocol',
  severity: 'breaking',
  mechanicallySafe: false,
  replacement: {
    api: 'widget.hidden = true (+ explicit serialization if it was coupled)',
    declaredAt: 'src/platform/nodeApi/widgetHandle.ts'
  },
  guidance: `
\`widget.type = 'converted-widget'\` was always emulating a property that did
not exist. It becomes:

    node.widgets.get(name).hidden = true

Everything the old helper saved and restored — \`origType\`,
\`origComputeSize\`, \`origSerializeValue\`, the \`[0, -4]\` size hack — goes
away with it.

**Check the serialization coupling first.** The old helper also installed a
\`serializeValue\` returning \`undefined\` unless the matching input was linked.
\`hidden\` is presentation only, so converting the type assignment alone makes a
hidden widget serialize where it previously did not. If the pack relied on that,
handle persistence explicitly in its own serialize hook.

\`widget.linkedWidgets\` recursion has no published equivalent — hide each widget
by name, or escalate.
`.trim(),
  apply(lines, report) {
    lines.forEach((line, i) => {
      if (line === null || !CONVERTED_WIDGET.test(line)) return
      report({
        line: i + 1,
        text: line.trim(),
        escalation:
          'hidden is presentation only; the old hack also suppressed serialization. Converting the type assignment alone can change the wire format.'
      })
    })
  },
  cases: [
    {
      name: 'string literal',
      before: "widget.type = 'converted-widget';",
      escalates: true
    },
    {
      name: 'via constant',
      before: 'widget.type = CONVERTED_TYPE + suffix;',
      escalates: true
    },
    {
      name: 'unrelated type assignment is not flagged',
      before: "widget.type = 'combo';",
      after: "widget.type = 'combo';"
    }
  ]
}

export const RULES: readonly MigrationRule[] = [
  typeWriteNoop,
  outputLinksMutation,
  inputLinkWrite,
  widgetsArrayMutation,
  convertedWidgetProtocol
]

/** Bumping this invalidates every cached artifact. */
export const RULE_CATALOG_VERSION = 2
